    {id="Mortis.AnatomicalFunction",title="Infected Anatomical Function"},
    {id="Mortis.StarvationDesiccation",title="Starvation and Desiccation"},
    {id="Mortis.PhysicalFailureModes",title="Infected Physical Failure Modes"},
}
