local documents={
    {id="MORTIS-93-001",category="FOUNDATION",classification="RESTRICTED",title="Persistent Postmortem Activity",date="07/09/1993",tier=1,itemType="ProjectMORTIS.Research_MORTIS_93_001",distribution={LaboratoryBooks=.08,TestingLab=.03,ArmyStorageMedical=.015,MedicalOfficeBooks=.01},references={"MORTIS-ANAT-012","NF-UV-003"},grantsKnowledge={"Mortis.BasicInfectedPhysiology"},content={"Observed subjects retain coordinated activity despite systemic death. ",{text="Feeding changes behavioral persistence but does not restore ordinary metabolism.",redacted=true,marker="████████████"}," Tissue trauma remains the most reliable predictor of functional impairment."}},
    {id="MORTIS-ANAT-012",category="ANATOMY",classification="RESTRICTED",title="Functional Anatomy After Death",tier=2,itemType="ProjectMORTIS.Research_MORTIS_ANAT_012",distribution={LaboratoryBooks=.045,TestingLab=.02,ArmyStorageMedical=.01},prerequisiteDocuments={"MORTIS-93-001"},references={"MORTIS-93-001","MORTIS-MECH-008"},grantsKnowledge={"Mortis.AnatomicalFunction"},content={"Loss of a region produces predictable functional consequences even when systemic physiology is absent. ",{text="Attachment and sever-state must be recorded by topology rather than inferred from appearance.",redacted=true,marker="██████████"}," Visual continuity is not reliable evidence of anatomical continuity."}},
    {id="MORTIS-MET-021",category="METABOLISM",classification="SECRET",title="Starvation Persistence Study",tier=2,itemType="ProjectMORTIS.Research_MORTIS_MET_021",distribution={LaboratoryBooks=.035,TestingLab=.015,ArmyStorageMedical=.008},prerequisiteKnowledge={"Mortis.BasicInfectedPhysiology"},references={"MORTIS-93-001"},grantsKnowledge={"Mortis.StarvationDesiccation"},content={"Subjects exhibit a persistent feeding drive independent of ordinary caloric recovery. Continuous deprivation produces extremely slow tissue desiccation measured in years, not days. ",{text="Terminal loss of function remains possible after prolonged uninterrupted starvation.",redacted=true,marker="████████████"}}},
    {id="MORTIS-MECH-008",category="BIOMECHANICS",classification="RESTRICTED",title="Balance and Collision Failure",tier=2,itemType="ProjectMORTIS.Research_MORTIS_MECH_008",distribution={LaboratoryBooks=.04,TestingLab=.02,ArmyStorageMedical=.006},prerequisiteDocuments={"MORTIS-93-001"},references={"MORTIS-ANAT-012"},grantsKnowledge={"Mortis.PhysicalFailureModes"},content={"Prone bodies, stairs, low obstacles, impacts, and dense groups alter balance through distinct mechanisms. Repeated falls in a pile are correlated rather than independent. ",{text="Group-level throttling is required to avoid cascade artifacts.",redacted=true,marker="████████"}}},
}
